  "item-48": {"description": "Summons an illusory lake.", "effect": "Use it where Mirage Lake vanished so you can follow the king to the hideout.", "type": "Quest item", "uses": {"text": "1 quest use", "sort": 1}, "sell": null, "sources": [{"game": "dqm2", "text": "Feed the hungry prisoner in Assia Dungeon.", "entry": "quest-mirage-lake-and-the-sea-bell"}]},
